import { toggleNotificationPreference, getNotificationPreference } from "./actions";

export default async function Home() {
  const notifications = await getNotificationPreference();

  return (
    <main>
      <h1>Settings</h1>
      <form action={toggleNotificationPreference}>
        <label>
          Notifications: <strong>{notifications}</strong>
        </label>
        <button type="submit">
          Toggle to {notifications === "on" ? "off" : "on"}
        </button>
      </form>
    </main>
  );
}

